    TdsDeduction = apps.get_model("purchasing", "TdsDeduction")
    untold = []
    for row in TdsDeduction.objects.filter(posted_account=None).order_by("pk"):
        credited = list(JournalLine.objects.filter(entry_id=row.journal_entry_id, credit__gt=0)
                        .values_list("account_id", flat=True))
        if len(credited) == 1:
            TdsDeduction.objects.filter(pk=row.pk).update(posted_account_id=credited[0])
        else:
            untold.append(f"TDS deduction {row.pk} of {row.amount} on bill {row.bill_id} ({row.date}): "
                          f"its entry {row.journal_entry_id} credits {len(credited)} lines")
